// legacy-effect-songs.ts
//
// Purpose: Songs built from the effect set that predates comb/flanger, with golden base64 strings recorded before that effect existed
//
// This module:
// - Builds one song per legacy effect bit (0 through 18) plus an all-effects song and a default song
// - Exports legacyGolden, the encodings produced by the pre-comb/flanger encoder

import { Song } from "../../synth/song";
import { Note, makeNotePin } from "../../synth/notes";
import { EffectType } from "../../synth/synth-config";

export function buildLegacySongs(): Record<string, Song> {
	const songs: Record<string, Song> = {};
	const make = (effects: number): Song => {
		const song: Song = new Song();
		song.title = "legacy";
		const instrument = song.channels[0].instruments[0];
		instrument.effects = effects;
		instrument.reverb = 5;
		instrument.chorus = 3;
		instrument.echoSustain = 4;
		instrument.distortion = 6;
		instrument.compressorThreshold = 17;
		instrument.compressorRatio = 7;
		instrument.compressorSync = 2;
		const pattern = song.channels[0].patterns[0];
		const note: Note = new Note(24, 0, 12, 6, false);
		note.pins = [makeNotePin(0, 0, 6), makeNotePin(0, 12, 3)];
		pattern.notes.push(note);
		return song;
	};
	songs.default = new Song();
	songs.default.title = "legacy";
	for (let bit = 0; bit <= EffectType.compressor; bit++) {
		if (bit === EffectType.octaveShift) continue;
		songs[`bit${bit}`] = make(1 << bit);
	}
	songs.allLegacy = make(0x3ffff & ~(1 << EffectType.octaveShift));
	songs.allLegacyWithCompressor = make(
		(0x3ffff & ~(1 << EffectType.octaveShift)) | (1 << EffectType.compressor),
	);
	return songs;
}

